// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Login watch: is each account still logged in
// Flo: no flag = read the saved login state (no network) and, when the last look is older than aliv_look_hour, one read-only look at ONE account per run (a failed look retries in 1 h, so it never starves the other account) > --live = look now > a dead login saves the state, alerts the owner (6 h gap) and exits 3; a good login or `fb-face-webs login` saves ok
// I/O: Ctx (caller) > one line per account; db meta alive_state (1 ok, 2 needs login) alive_at alive_note; exit 0 ok · 1 unknown · 3 needs login
// ===================================================================
const std = @import("std"); const task = @import("ru-task-runn.zig"); const halt = @import("ru-safe-halt.zig"); const wait = @import("ru-wait-hand.zig"); const pace = @import("ru-huma-pace.zig");
const CF = .{ .stat = "alive_state", .when = "alive_at", .note = "alive_note", .poll = 2000, .wait = 30000, .minz = 10, .cool = 6 * 3600 * 1000 };
pub const OK: i64 = 1; pub const DEAD: i64 = 2;
var looked: bool = false;
pub fn dueLook(state: i64, at: i64, now: i64, hours: u32) bool { if (state == DEAD) return false; return at == 0 or now - at >= @as(i64, hours) * 3600 * 1000; }
pub fn takeLook(store: *@import("st-stat-main.zig").Stat, conf: @import("cf-conf-load.zig").Conf, now: i64, acct: []const u8) bool { if (looked or pace.quietFor(now, conf.quie_zone_minu, conf.quie_hour_rang, acct)) return false; const st = store.metaGet(CF.stat) catch 0; const at = store.metaGet(CF.when) catch 0; if (!dueLook(st, at, now, conf.aliv_look_hour)) return false; looked = true; store.metaSet(CF.when, now - (@as(i64, conf.aliv_look_hour) - 1) * 3600 * 1000) catch {}; return true; }
pub fn markPut(ctx: *task.Ctx, state: i64) void { ctx.store.metaSet(CF.stat, state) catch {}; ctx.store.metaSet(CF.when, wait.realMs(ctx.iozz)) catch {}; }
pub fn coolOk(now: i64, noted: i64) bool { return noted > 0 and now - noted < CF.cool; }
fn loginCmd(ctx: *task.Ctx) []const u8 { const dirz = std.process.executableDirPathAlloc(ctx.iozz, ctx.aren) catch return "fb-face-webs"; const exe = std.fs.path.join(ctx.aren, &.{ dirz, if (@import("builtin").os.tag == .windows) "fb-face-webs.exe" else "fb-face-webs" }) catch return "fb-face-webs"; return std.fmt.allocPrint(ctx.aren, "\"{s}\"", .{exe}) catch "fb-face-webs"; }
fn tellDead(ctx: *task.Ctx) void { const now = wait.realMs(ctx.iozz); const line = std.fmt.allocPrint(ctx.aren, "account {s} needs login: run {s} login --acct {s}", .{ ctx.acct, loginCmd(ctx), ctx.acct }) catch return; markPut(ctx, DEAD); if (coolOk(now, ctx.store.metaGet(CF.note) catch 0)) { task.say(ctx, "{s}", .{line}); return; } wait.notify(ctx, line); ctx.store.metaSet(CF.note, now) catch {}; }
fn liveChek(ctx: *task.Ctx) !u8 { if (pace.quietFor(wait.realMs(ctx.iozz), ctx.conf.quie_zone_minu, ctx.conf.quie_hour_rang, ctx.acct)) { task.say(ctx, "account {s}: quiet hours, check skipped", .{ctx.acct}); return 0; } ctx.page.arm(ctx.conf.brow_time_seco * 1000); try ctx.page.navigate(ctx.aren, ctx.base); var spent: u64 = 0; while (spent <= CF.wait) : (spent += CF.poll) { ctx.page.arm(ctx.conf.brow_time_seco * 1000); const urlz = ctx.page.urlNow(ctx.aren) catch ""; const txt = ctx.page.textNow(ctx.aren) catch ""; if (txt.len >= CF.minz) { if (halt.check(urlz, txt, "")) |kind| { if (halt.isLogout(kind)) { tellDead(ctx); return 3; } if (halt.classOf(kind) == .unsafe) return error.Unsafe; return error.Halted; } markPut(ctx, OK); task.say(ctx, "account {s}: logged in", .{ctx.acct}); return 0; } pace.nap(ctx.iozz, CF.poll, ctx.conf.time_scal_perc); } task.say(ctx, "account {s}: unknown (page did not draw in time)", .{ctx.acct}); return 1; }
pub fn aliveRun(ctx: *task.Ctx) !u8 { if (ctx.mode == .live or ctx.mode == .force or ctx.look) return liveChek(ctx); const st = ctx.store.metaGet(CF.stat) catch 0; if (st == DEAD) { tellDead(ctx); return 3; } task.say(ctx, "account {s}: {s}", .{ ctx.acct, if (st == OK) "ok" else "unknown (not checked yet)" }); return 0; }
